    {
      "label": "H2: Operator‑induced bias or data‑entry error on day 10",
      "probability": 0.15,
      "rationale": "If the same technician recorded the pendulum_obs trials, a consistent offset (e.g., reading the stopwatch slightly early) could produce a downward trend. No independent verification of the recordings is available.",
      "evidenceFor": ["781490", "644500", "12299", "71897", "10878", "298406"],
      "evidenceAgainst": []
    },
    {
      "label": "H3: Mechanical change in the pendulum (e.g., wire stretch or tension loss)",
      "probability": 0.10,
      "rationale": "A gradual change in the pendulum’s effective length could lower its period. However, the change appears abrupt over a single day, making this less likely without prior evidence of wear.",
      "evidenceFor": ["781490", "644500", "12299", "71897", "10878", "298406"],
      "evidenceAgainst": []
    },
    {
      "label": "H4: External vibration or magnetic interference affecting the pendulum during day 10",
      "probability": 0.03,
      "rationale": "Transient disturbances (e.g., nearby machinery) could alter the swing amplitude, but no logs record such events, and the effect would likely be more erratic than a smooth trend.",
      "evidenceFor": [],
